package de.eldoria.bloodnight.generated;

import de.eldoria.bloodnight.api.CompiledBehaviour;
import de.eldoria.bloodnight.api.MobContext;
import de.eldoria.bloodnight.graph.runtime.BukkitRuntime;
import de.eldoria.bloodnight.graph.runtime.Registries;
import de.eldoria.graph.std.runtime.Cooldown;
import de.eldoria.graph.std.runtime.TimeUnit;
import io.papermc.paper.registry.RegistryKey;
import org.bukkit.Particle;
import org.bukkit.entity.Entity;
import org.bukkit.entity.Phantom;
import org.bukkit.entity.Player;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;

public final class FearfulPhantomBehaviour implements CompiledBehaviour {
    private static final PotionEffectType SLOWNESS = Registries.entry(RegistryKey.MOB_EFFECT, "minecraft:slowness");

    private static final Particle CAMPFIRE_COSY_SMOKE = Registries.entry(RegistryKey.PARTICLE_TYPE, "minecraft:campfire_cosy_smoke");

    private static final TimeUnit MILLISECONDS = TimeUnit.MILLISECONDS;

    private static final PotionEffectType GLOWING = Registries.entry(RegistryKey.MOB_EFFECT, "minecraft:glowing");

    private final MobContext context;

    private Cooldown cooldown;

    public FearfulPhantomBehaviour(MobContext context) {
        this.context = context;
        // node #24 function.cooldown
        this.cooldown = new Cooldown();
    }

    @Override
    public void onHit(EntityDamageByEntityEvent event) {
        // node #7 event.hit
        // node #11 flow.branch
        // node #8 event.hit
        final Entity entity = event.getEntity();
        if (!(entity instanceof Player)) return;
        // node #10 living_entity.apply_effect
        // node #9 cast
        final Player cast = (entity instanceof Player ? (Player) entity : null);
        cast.addPotionEffect(new PotionEffect(SLOWNESS, (int) (7.0d * 20), 2, true, true));
        // node #12
    }

    @Override
    public void onNightEnd() {
        // node #19 mob.night_end
        // node #21 world.spawn_particle
        // node #20 mob.self
        final Phantom self = ((Phantom) this.context.entity());
        BukkitRuntime.particles(this.context, self.getWorld(), CAMPFIRE_COSY_SMOKE, self.getEyeLocation(), 30, 1.5d, 1.0d, 1.5d, null);
        // node #22
    }

    @Override
    public void onTick() {
        // node #30 mob.tick
        // node #33 flow.branch
        // node #31 function.cooldown
        final boolean cooldown = this.cooldown.ready(MILLISECONDS.toMillis(30000.0d));
        if (!cooldown) return;
        // node #32 living_entity.apply_effect
        ((Phantom) this.context.entity()).addPotionEffect(new PotionEffect(GLOWING, (int) (60.0d * 20), 1, true, true));
        // node #34
    }
}
